class NavienSmartBothThermostat(NavienSmartThermostat):
    """좌·우 통합 온도조절. **명령은 언제나 한 번에 양쪽을 싣는다.**

    - 온도 설정 → 두 구역에 같은 값, 명령 1건. 꺼져 있으면 저장만 한다(v0.21.0)
    - 켜기 → 꺼져 있던 구역만 최저값으로 올림 (`build_zone_on`), 명령 1건
    - 끄기 → 기기가 마지막 구역을 끄는 것을 막으므로 **전원을 끈다**
    """

    _attr_icon = "mdi:bed"

    def __init__(
        self,
        coordinator: NavienSmartCoordinator,
        device: NavienDevice,
    ) -> None:
        super().__init__(coordinator, device, device.zones[0])
        self._attr_unique_id = f"{device.device_id}_both_thermostat"
        self._attr_name = "좌우 통합"

    @property
    def _target_zones(self) -> tuple[str, ...]:
        device = self.device
        return device.zones if device is not None else ()

    def _on_zones(self) -> list[str]:
        device = self.device
        if device is None:
            return []
        return [z for z in device.zones if device.zone_enabled(z) is not False]

    @property
    def current_temperature(self) -> float | None:
        device = self.device
        if device is None:
            return None
        values = [v for z in device.zones if (v := device.zone_current(z)) is not None]
        return max(values) if values else None

    @property
    def target_temperature(self) -> float | None:
        """켜진 구역 중 높은 값. 전부 꺼졌으면 좌측 설정값."""
        device = self.device
        if device is None:
            return None
        zones = self._on_zones() if device.is_on else []
        zones = zones or list(device.zones[:1])
        values = [v for z in zones if (v := device.zone_setting(z)) is not None]
        return max(values) if values else None

    @property
    def hvac_mode(self) -> HVACMode | None:
        device = self.device
        if device is None or device.operation_mode is None:
            return None
        if not device.is_on or not self._on_zones():
            return HVACMode.OFF
        return HVACMode.COOL if device.is_cooling else HVACMode.HEAT

    @property
    def extra_state_attributes(self) -> dict[str, Any] | None:
        """상세 화면 「속성」 칸에 좌·우 설정값을 따로 보여준다.

        서모스탯 화면은 설정 다이얼이 하나뿐이라 좌우가 다르면 한쪽 값만 보인다.
        키를 한글로 둔 것은 속성 칸에 키가 그대로 이름으로 표시되기 때문이다.
        꺼진 구역의 설정값은 꺼짐용 값(27.5)이라 숫자 대신 「꺼짐」으로 적는다.
        """
        attrs = super().extra_state_attributes
        device = self.device
        if attrs is None or device is None:
            return attrs
        attrs.pop("zone", None)
        for zone in device.zones:
            label = device.zone_names.get(zone) or ZONE_NAMES.get(zone, zone)
            value = device.zone_setting(zone)
            if not device.is_on or device.zone_enabled(zone) is False:
                text = "꺼짐"
            elif value is None:
                text = "—"
            else:
                text = f"{value:g}°"
            attrs[f"{label} 설정"] = text
        return attrs

    async def async_set_hvac_mode(self, hvac_mode: HVACMode) -> None:
        device = self.device
        if device is None:
            return
        if hvac_mode is HVACMode.OFF:
            # 좌우 분리 매트는 마지막 한쪽을 끌 수 없다. 통합 엔티티의 「끄기」는 전원이다.
            await self.coordinator.async_send(device, {"operationMode": MODE_POWER_OFF})
            return
        await self.coordinator.async_send(device, device.build_zone_on(device.zones))
